func vector(compact bool)map[string]interface{}{var seed [32]byte;for i:=range seed{seed[i]=byte(i)};pub,priv:=mldsa87.NewKeyFromSeed(&seed);var to common.Address;for i:=range to{to[i]=byte(i+1)};if compact{for i:=0;i<16;i++{to[i]=0}};signer:=types.NewEIP155Signer(big.NewInt(1));makeTx:=func(nonce uint64,gasPrice int64,dest common.Address)*types.Transaction{return types.NewTx(&types.LegacyTx{Nonce:nonce,GasPrice:big.NewInt(gasPrice),Gas:1000,To:&dest,Value:big.NewInt(123456789),Data:[]byte{}})};unsigned:=makeTx(7,2000000000,to);digest:=signer.Hash(unsigned);signed,err:=types.SignTxMLDSA87(unsigned,signer,priv);if err!=nil{panic(err)};raw,err:=signed.MarshalBinary();if err!=nil{panic(err)};var decoded types.Transaction;if err=decoded.UnmarshalBinary(raw);err!=nil{panic(err)};from,err:=types.Sender(signer,&decoded);if err!=nil{panic(err)};sig:=append([]byte{1},pub.Bytes()...);sig=append(sig,signed.SignatureBytes()...);badTo:=to;badTo[47]^=1;for _,bad:=range []*types.Transaction{makeTx(8,2000000000,to),makeTx(7,2000000001,to),makeTx(7,2000000000,badTo)}{bad,err=bad.WithSignature(signer,sig);if err!=nil{panic(err)};if _,err=types.Sender(signer,bad);err==nil{panic("altered transaction accepted")}};if _,err=types.Sender(types.NewEIP155Signer(big.NewInt(2)),signed);err==nil{panic("wrong chain accepted")};sig[len(sig)-1]^=1;bad,err:=unsigned.WithSignature(signer,sig);if err!=nil{panic(err)};if _,err=types.Sender(signer,bad);err==nil{panic("altered signature accepted")};return map[string]interface{}{"compact":compact,"seed":hex.EncodeToString(seed[:]),"to":hex.EncodeToString(to[:]),"nonce":"7","gasPrice":"2000000000","gas":"1000","value":"123456789","signingHash":hex.EncodeToString(digest[:]),"publicKey":hex.EncodeToString(pub.Bytes()),"signature":hex.EncodeToString(signed.SignatureBytes()),"raw":hex.EncodeToString(raw),"txHash":signed.Hash().Hex(),"sender":from.Hex()}}
